// Promise basics: connect “fetch user -> fetch orders -> fetch shipment” as one chain; each then receives the previous result, so the next request does not need another nested callback.
fetchUser(id)
  .then(user => fetchOrders(user.id)) // Fetch the user first, then use the user ID to request orders.
  .then(orders => fetchShipment(orders[0].id)) // Read the first order's shipment; the returned value continues to the next then.
  .then(ship => console.log('Package status:', ship.status)) // Print the final status after every request succeeds.
  .catch(err => console.error('Something went wrong:', err)); // Any failure flows here instead of requiring duplicate handling at every level.

// Promise.all: wait for independent async tasks in parallel; user and config become available together only after both tasks finish.
const [user, config] = await Promise.all([
  fetchUser(id),
  fetchConfig()
]);

